def is_valid(grid):
    # Check rows
    for r in range(4):
        row = [grid[r*4 + c] for c in range(4)]
        if len(set(row)) != 4 or 0 in row:
            return False
    # Check columns
    for c in range(4):
        col = [grid[r*4 + c] for r in range(4)]
        if len(set(col)) != 4 or 0 in col:
            return False
    # Check blocks
    for br in range(0, 4, 2):
        for bc in range(0, 4, 2):
            block = []
            for r in range(br, br+2):
                for c in range(bc, bc+2):
                    block.append(grid[r*4 + c])
            if len(set(block)) != 4 or 0 in block:
                return False
    return True

def solve(grid, index):
    if index == 16:
        return grid if is_valid(grid) else None

    if grid[index] != 0:
        return solve(grid, index + 1)

    for val in range(1, 5):
        grid[index] = val
        # Optimization: check partial validity
        # (Not strictly necessary for 4x4, but good practice)
        result = solve(grid, index + 1)
        if result:
            return result
        grid[index] = 0
    return None

# Initial grid
grid = [0] * 16
grid[7] = 2
grid[9] = 1
grid[12] = 4

solution = solve(grid, 0)
print(solution)
